source='''import math


def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    marks = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] not in (0, 8)]
    if not cells or not marks:
        return [row[:] for row in grid]

    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
    runs = []
    for r in range(r0, r1 + 1):
        c = c0
        while c <= c1:
            if grid[r][c] == 8:
                start = c
                while c <= c1 and grid[r][c] == 8:
                    c += 1
                runs.append(c - start)
            else:
                c += 1
    for c in range(c0, c1 + 1):
        r = r0
        while r <= r1:
            if grid[r][c] == 8:
                start = r
                while r <= r1 and grid[r][c] == 8:
                    r += 1
                runs.append(r - start)
            else:
                r += 1
    tile = 0
    for run in runs:
        tile = math.gcd(tile, run)

    mr0, mr1 = min(r for r, c, v in marks), max(r for r, c, v in marks)
    mc0, mc1 = min(c for r, c, v in marks), max(c for r, c, v in marks)
    key = [[0] * (mc1 - mc0 + 1) for _ in range(mr1 - mr0 + 1)]
    for r, c, value in marks:
        key[r - mr0][c - mc0] = value
    rotated = [list(row) for row in zip(*key[::-1])]

    output = [row[:] for row in grid]
    for r, c in cells:
        output[r][c] = rotated[(r - r0) // tile][(c - c0) // tile]
    return output
'''
